use crunch_release_core::DeterministicBuildProofReceipt;
use crunch_rust_cache_core::slots::SlotReceipt;

fn main() {
    let path = std::env::args_os().nth(1).expect("receipt path required");
    let bytes = std::fs::read(path).expect("retained native scheduling receipt must be readable");
    let receipt: SlotReceipt = serde_json::from_slice(&bytes).expect("retained receipt must parse as SlotReceipt");
    assert!(receipt.is_grant_for(&receipt.build_id), "retained native receipt is not a valid grant");
    let rejection = serde_json::from_slice::<DeterministicBuildProofReceipt>(&bytes)
        .expect_err("a scheduling grant must never be accepted as deterministic build proof");
    println!("{}", serde_json::json!({
        "scheduling_schema": receipt.schema,
        "native_grant_valid": true,
        "deterministic_build_proof_accepted": false,
        "rejection": rejection.to_string(),
        "proof_executed": false,
        "scope": "Production core receipt types only; no release, source-built bundle or representative bootstrap claim"
    }));
}
